        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void AddText(ImFontGlyphRangesBuilderPtr self, string text, string? textEnd)
        {
            nint p_text = 0;
            nint p_textEnd = 0;
            try
            {
                p_text = text is null ? 0 : Marshal.StringToCoTaskMemUTF8(text);
                p_textEnd = textEnd is null ? 0 : Marshal.StringToCoTaskMemUTF8(textEnd);
                AddTextNative((ImFontGlyphRangesBuilder*)self.Handle, (byte*)p_text, (byte*)p_textEnd);
            }
            finally
            {
                if (p_text != 0)
                    Marshal.FreeCoTaskMem(p_text);
                if (p_textEnd != 0)
                    Marshal.FreeCoTaskMem(p_textEnd);
            }
        }

