        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static uint GetID(ImGuiWindowPtr self, string str, string? strEnd)
        {
            nint p_str = 0;
            nint p_strEnd = 0;
            try
            {
                p_str = str is null ? 0 : Marshal.StringToCoTaskMemUTF8(str);
                p_strEnd = strEnd is null ? 0 : Marshal.StringToCoTaskMemUTF8(strEnd);
                return GetIDNative((ImGuiWindow*)self.Handle, (byte*)p_str, (byte*)p_strEnd);
            }
            finally
            {
                if (p_str != 0)
                    Marshal.FreeCoTaskMem(p_str);
                if (p_strEnd != 0)
                    Marshal.FreeCoTaskMem(p_strEnd);
            }
        }

