    /// <summary>
    /// Represents a texture handle passed to ImGui functions like <see cref = "ImGui.Image(ImTextureID, Vector2)"/>.
    /// </summary>
    [DebuggerDisplay("{DebuggerDisplay,nq}")]
    public readonly partial struct ImTextureID : IEquatable<ImTextureID>
    {
        public ImTextureID(ulong handle)
        {
            Handle = handle;
        }

        public ImTextureID(nint handle)
        {
            Handle = (ulong)handle;
        }

        public ImTextureID(nuint handle)
        {
            Handle = (ulong)handle;
        }

        public unsafe ImTextureID(void* handle)
        {
            Handle = (ulong)handle;
        }

        public ulong Handle { get; }
        public bool IsNull => Handle == 0;
        public static ImTextureID Null => new ImTextureID(0UL);

        public static implicit operator ImTextureID(ulong handle) => new ImTextureID(handle);
        public static implicit operator ImTextureID(nint handle) => new ImTextureID(handle);
        public static implicit operator ImTextureID(nuint handle) => new ImTextureID(handle);
        public static unsafe implicit operator ImTextureID(void* handle) => new ImTextureID(handle);
        public static implicit operator ulong (ImTextureID handle) => handle.Handle;
        public static implicit operator nint(ImTextureID handle) => (nint)handle.Handle;
        public static implicit operator nuint(ImTextureID handle) => (nuint)handle.Handle;
        public static unsafe implicit operator void*(ImTextureID handle) => (void*)handle.Handle;
        public static bool operator ==(ImTextureID left, ImTextureID right) => left.Handle == right.Handle;
        public static bool operator !=(ImTextureID left, ImTextureID right) => left.Handle != right.Handle;
        public static bool operator ==(ImTextureID left, ulong right) => left.Handle == right;
        public static bool operator !=(ImTextureID left, ulong right) => left.Handle != right;
        public static bool operator ==(ImTextureID left, nint right) => left.Handle == (ulong)right;
        public static bool operator !=(ImTextureID left, nint right) => left.Handle != (ulong)right;
        public static bool operator ==(ImTextureID left, nuint right) => left.Handle == right;
        public static bool operator !=(ImTextureID left, nuint right) => left.Handle != right;
        public static unsafe bool operator ==(ImTextureID left, void* right) => left.Handle == (ulong)right;
        public static unsafe bool operator !=(ImTextureID left, void* right) => left.Handle != (ulong)right;
        public bool Equals(ImTextureID other) => Handle == other.Handle;
        /// <inheritdoc/>
        public override bool Equals(object? obj) => obj is ImTextureID handle && Equals(handle);
        /// <inheritdoc/>
        public override int GetHashCode() => Handle.GetHashCode();
        private string DebuggerDisplay => string.Format("ImTextureID [0x{0}]", Handle.ToString("X"));
    }

    /// <summary>
    /// A structure representing the native ImVector layout for unmanaged types.
    /// </summary>
    /// <typeparam name = "T">
    /// The type of elements in the vector, must be unmanaged.
    /// </typeparam>
    [StructLayout(LayoutKind.Sequential)]
    public unsafe struct ImVector<T>
        where T : unmanaged
    {
        /// <summary>
        /// Initializes a new instance of the <see cref = "ImVector{T}"/> struct with the specified size, capacity, and data pointer.
        /// </summary>
        /// <param name = "size">
        /// The initial size of the vector.
        /// </param>
        /// <param name = "capacity">
        /// The initial capacity of the vector.
        /// </param>
        /// <param name = "data">
        /// Pointer to the initial data.
        /// </param>
        public ImVector(int size, int capacity, T* data)
        {
            this.size = size;
            this.capacity = capacity;
            this.data = data;
        }

        private int size;
        private int capacity;
        private unsafe T* data;
        /// <summary>
        /// Gets or sets the element at the specified index.
        /// </summary>
        /// <param name = "index">
        /// The zero-based index of the element to get or set.
        /// </param>
        /// <returns>
        /// The element at the specified index.
        /// </returns>
        /// <exception cref = "IndexOutOfRangeException">
        /// Thrown when the index is out of range.
        /// </exception>
        public T this[int index]
        {
            get
            {
                if (data == null || index < 0 || index >= size)
                {
                    throw new IndexOutOfRangeException();
                }

                return data[index];
            }

            set
            {
                if (data == null || index < 0 || index >= size)
                {
                    throw new IndexOutOfRangeException();
                }

                data[index] = value;
            }
        }

        /// <summary>
        /// Gets a pointer to the first element of the vector.
        /// </summary>
        public readonly T* Data => data;
        /// <summary>
        /// Gets a pointer to the first element of the vector.
        /// </summary>
        public readonly T* Front => data;
        /// <summary>
        /// Gets a pointer to the last element of the vector.
        /// </summary>
        public readonly T* Back => size > 0 ? data + size - 1 : null;

        /// <summary>
        /// Gets or sets the capacity of the vector.
        /// </summary>
        public int Capacity
        {
            readonly get => capacity;
            set
            {
                ArgumentOutOfRangeException.ThrowIfNegative(value);
                if (capacity == value)
                {
                    return;
                }

                if (value == 0)
                {
                    Free();
                    return;
                }

                nuint bytes = checked((nuint)value * (nuint)sizeof(T));
                if (data == null)
                {
                    data = (T*)ImGui.MemAlloc(bytes);
                    if (data == null)
                        throw new OutOfMemoryException();
                }
                else
                {
                    int newSize = Math.Min(size, value);
                    T* newData = (T*)ImGui.MemAlloc(bytes);
                    if (newData == null)
                        throw new OutOfMemoryException();
                    Buffer.MemoryCopy(data, newData, bytes, checked((nuint)newSize * (nuint)sizeof(T)));
                    ImGui.MemFree(data);
                    data = newData;
                    size = newSize;
                }

                capacity = value;
                // Clear the rest of the data
                for (int i = size; i < capacity; i++)
                {
                    data[i] = default;
                }
            }
        }

        /// <summary>
        /// Gets the number of elements in the vector.
        /// </summary>
        public readonly int Size => size;

        /// <summary>
        /// Grows the capacity of the vector to at least the specified value.
        /// </summary>
        /// <param name = "newCapacity">
        /// The new capacity.
        /// </param>
        public void Grow(int newCapacity)
        {
            ArgumentOutOfRangeException.ThrowIfNegative(newCapacity);
            if (newCapacity > capacity)
            {
                Capacity = checked(newCapacity * 2);
            }
        }

        /// <summary>
        /// Ensures that the vector has at least the specified capacity.
        /// </summary>
        /// <param name = "size">
        /// The minimum capacity required.
        /// </param>
        public void EnsureCapacity(int size)
        {
            ArgumentOutOfRangeException.ThrowIfNegative(size);
            if (size > capacity)
            {
                Grow(size);
            }
        }

        /// <summary>
        /// Resizes the vector to the specified size.
        /// </summary>
        /// <param name = "newSize">
        /// The new size of the vector.
        /// </param>
        public void Resize(int newSize)
        {
            ArgumentOutOfRangeException.ThrowIfNegative(newSize);
            EnsureCapacity(newSize);
            size = newSize;
        }

        /// <summary>
        /// Clears all elements from the vector.
        /// </summary>
        public void Clear()
        {
            size = 0;
        }

        /// <summary>
        /// Adds an element to the end of the vector.
        /// </summary>
        /// <param name = "value">
        /// The value to add.
        /// </param>
        public void PushBack(T value)
        {
            EnsureCapacity(checked(size + 1));
            data[size++] = value;
        }

        /// <summary>
        /// Removes the last element from the vector.
        /// </summary>
        public void PopBack()
        {
            if (size > 0)
            {
                size--;
            }
        }

        /// <summary>
        /// Frees the memory allocated for the vector.
        /// </summary>
        public void Free()
        {
            if (data != null)
            {
                ImGui.MemFree(data);
                data = null;
                size = 0;
                capacity = 0;
            }
        }
    }
}
